{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 1,
      "content": {
        "json": "# Azure update and software inventory\nSCCM-inspired reporting from Change Tracking and Inventory data in Log Analytics."
      },
      "name": "header"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "parameters": [
          {
            "id": "5f95e04f-c6a8-4594-bbf2-732224322b61",
            "version": "KqlParameterItem/1.0",
            "name": "Workspace",
            "label": "Log Analytics workspace",
            "type": 5,
            "isRequired": true,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "query": "where type =~ \"microsoft.operationalinsights/workspaces\"\n| project id, name\n| sort by name asc",
            "crossComponentResources": [
              "value::all"
